#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void test_buffer_overflow_scenarios() {
    printf("Testing buffer overflow scenarios...\n");

    // Test case 1: Copy larger page than destination capacity
    // This should trigger a buffer overflow if the function doesn't validate properly
    const size_t small_capacity = 100;
    char* dst_page = malloc(small_capacity);
    char* large_src_page = malloc(small_capacity * 2);  // Source is larger than destination capacity

    // Initialize source with known pattern
    for (size_t i = 0; i < small_capacity * 2; i++) {
        large_src_page[i] = (char)(i % 256);
    }

    // This call should either fail safely or trigger sanitizer if vulnerable
    int result = copy_vm_memory_page(large_src_page, small_capacity * 2, dst_page, small_capacity);

    free(large_src_page);
    free(dst_page);

    // Test case 2: Edge case with page_size equal to capacity + 1
    const size_t capacity = 512;
    char* dst_page2 = malloc(capacity);
    char* src_page2 = malloc(capacity + 1);

    for (size_t i = 0; i < capacity + 1; i++) {
        src_page2[i] = (char)(i % 128);
    }

    result = copy_vm_memory_page(src_page2, capacity + 1, dst_page2, capacity);

    free(src_page2);
    free(dst_page2);

    // Test case 3: Very large page size that could cause integer overflow
    char dummy_src[100];
    char dummy_dst[100];

    // Try with a large page size that exceeds destination capacity
    result = copy_vm_memory_page(dummy_src, (size_t)-1, dummy_dst, 100);

    // Test case 4: Page size of 0 with valid pointers (boundary condition)
    result = copy_vm_memory_page(dummy_src, 0, dummy_dst, 100);

    printf("Buffer overflow tests completed\n");
}

int main() {
    printf("Running security tests with sanitizers enabled...\n");

    test_buffer_overflow_scenarios();

    printf("Security tests completed\n");
    return 0;
}

